/*
 * O seletor de tags do painel (o "Me too", a resposta automática do
 * assistente): as tags carregam uma vez por visita ao admin, primárias com as
 * filhas logo abaixo e as secundárias no fim.
 */
import app from 'flarum/admin/app';
import { AdminComponent, getStr, saveSetting, trans } from '../util';
/** As tags carregam uma vez por visita ao admin; o card redesenha várias. */
let tagRows = null;
let tagsLoading = false;
function loadTags() {
  if (tagRows || tagsLoading) return;
  tagsLoading = true;
  app.store.find('tags', {
    include: 'parent'
  }).then(tags => {
    // Primárias em ordem, cada uma seguida das filhas; as secundárias (sem
    // posição) no fim, em ordem alfabética, como na página de tags.
    const all = [...tags];
    const primary = all.filter(tag => tag.position() !== null && !tag.parent()).sort((a, b) => a.position() - b.position());
    const rows = [];
    const row = (tag, depth) => ({
      id: String(tag.id()),
      name: tag.name(),
      color: tag.color() || '',
      depth
    });
    for (const tag of primary) {
      rows.push(row(tag, 0));
      all.filter(child => child.parent() === tag).sort((a, b) => (a.position() ?? 0) - (b.position() ?? 0)).forEach(child => rows.push(row(child, 1)));
    }
    all.filter(tag => tag.position() === null && !tag.parent()).sort((a, b) => a.name().localeCompare(b.name())).forEach(tag => rows.push(row(tag, 0)));
    tagRows = rows;
  }).catch(() => {
    tagRows = [];
  }).finally(() => {
    tagsLoading = false;
    m.redraw();
  });
}

/**
 * A lista de tags com caixas de seleção, gravada como ids separados por
 * vírgula em `settingKey`. Os textos vêm de `transKey` (tags_label,
 * tags_help, tags_loading, tags_some, tags_all, tags_clear): quem usa decide
 * o que "nenhuma marcada" quer dizer.
 */
export default class AdminTagPicker extends AdminComponent {
  oninit(vnode) {
    super.oninit(vnode);
    loadTags();
  }
  view() {
    const {
      settingKey,
      transKey
    } = this.attrs;
    const selected = new Set(getStr(settingKey).split(',').map(id => id.trim()).filter(Boolean));
    const save = next => {
      const value = [...next].join(',');
      app.data.settings[settingKey] = value;
      saveSetting({
        [settingKey]: value
      });
    };
    return m("div", {
      className: "Form-group CanelaAdmin-tagPicker"
    }, m("label", null, trans(`${transKey}.tags_label`)), m("p", {
      className: "helpText"
    }, trans(`${transKey}.tags_help`)), !tagRows ? m("p", {
      className: "helpText"
    }, trans(`${transKey}.tags_loading`)) : m('[', null, m("p", {
      className: "CanelaAdmin-tagPicker-summary"
    }, selected.size ? trans(`${transKey}.tags_some`, {
      count: selected.size
    }) : trans(`${transKey}.tags_all`), selected.size > 0 && m("button", {
      type: "button",
      className: "Button Button--link",
      onclick: () => save(new Set())
    }, trans(`${transKey}.tags_clear`))), m("ul", {
      className: "CanelaAdmin-tagPicker-list"
    }, tagRows.map(tag => m("li", {
      key: tag.id,
      className: tag.depth ? 'is-child' : ''
    }, m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      checked: selected.has(tag.id),
      onchange: event => {
        const next = new Set(selected);
        event.target.checked ? next.add(tag.id) : next.delete(tag.id);
        save(next);
      }
    }), m("span", {
      className: "CanelaAdmin-tagPicker-swatch",
      style: {
        background: tag.color || 'var(--control-bg)'
      }
    }), tag.name))))));
  }
}
flarum.reg.add('ramon-canela', 'admin/components/AdminTagPicker', AdminTagPicker);